def to_float(text):
    """A finite float from an NMEA field, or None when the field is empty or not a number.

    Example: to_float("0.72") → 0.72;  to_float("") → None;  to_float("1.0.6") → None
    """
    try:
        v = float(text) if text not in (None, "") else None
    except (TypeError, ValueError):
        return None
    return v if v is None or math.isfinite(v) else None


# given — read it and use it, no need to change it
def to_int(text):
    """An int from an NMEA field, or None when it is empty or not a whole number.

    Example: to_int("08") → 8;  to_int("") → None
    """
    try:
        return int(text) if text not in (None, "") else None
    except (TypeError, ValueError):
        return None


# given — read it and use it, no need to change it
def fields(line):
    """The comma-separated fields of a VALID sentence, without "$" and "*hh"; None for an invalid line.
    fields(line)[0] is the address (talker + type, e.g. "GPGGA"); fields(line)[k] is field k of the standard.

    Example: fields("$GPGSA,A,1*32") → ["GPGSA", "A", "1"]
    """
    if not is_valid(line):
        return None
    return line.strip()[1:].split("*", 1)[0].split(",")


# given — read it and use it, no need to change it
def sentence_type(line):
    """The 3-letter type of a valid sentence ("GGA", "RMC", "GSA", "GSV"…), or None.

    Example: sentence_type("$GPGSA,A,1*32") → "GSA"
    """
    f = fields(line)
    return f[0][-3:] if f else None


# given — read it and use it, no need to change it
def utc_seconds(hhmmss):
    """An NMEA UTC time "hhmmss.ss" in seconds since midnight (float), or None.

    Example: utc_seconds("141621.00") → 51381.0
    """
    try:
        h, m, s = int(hhmmss[0:2]), int(hhmmss[2:4]), float(hhmmss[4:])
    except (TypeError, ValueError, IndexError):
        return None
    if not (0 <= h < 24 and 0 <= m < 60 and 0 <= s < 61):
        return None
    return h * 3600 + m * 60 + s


