# given — read it and use it, no need to change it
def parse_gsv(line):
    """One GSV sentence (satellites in view) → a dict, or None when the line is not a valid GSV.
    A GSV carries up to 4 satellites in blocks of 4 fields: PRN, elevation (°), azimuth (°), SNR (dB-Hz,
    empty when the satellite is in view but not tracked). A last item that does not make a full block
    (NMEA 4.10's signal ID) is ignored; a block without a PRN is skipped.

    Returns {"n_msgs": int, "msg": int, "in_view": int, "sats": [(prn, el_deg, az_deg, snr), …]}, each value
    an int or None.
    Example: parse_gsv("$GPGSV,3,1,12,02,61,008,45,05,31,051,38,07,20,097,34,09,45,130,41*7F")["sats"][0]
             → (2, 61, 8, 45)
    """
    f = fields(line)
    if f is None or not f[0].endswith("GSV") or len(f) < 4:
        return None
    sats = []
    rest = f[4:]
    for k in range(0, len(rest) - 3, 4):
        prn, el, az, snr = (to_int(x) for x in rest[k:k + 4])
        if prn is not None:
            sats.append((prn, el, az, snr))
    return {"n_msgs": to_int(f[1]), "msg": to_int(f[2]), "in_view": to_int(f[3]), "sats": sats}


# given — read it and use it, no need to change it
def read_log(path):
    """Every line of an NMEA log file, as str. Bytes that are not ASCII become "�" (they never crash
    the reader; the checksum then refuses the line).

    Example: read_log("/data/academy/15-gps-nmea/sousse_drive.nmea")[0][:6] → "$GPGGA"
    """
    with open(path, "rb") as f:
        return f.read().decode("ascii", errors="replace").splitlines()


